#!/usr/bin/env python3
"""Build a presentation-first SWE-EvalPressure team briefing from canonical current analysis outputs.

This script is presentation-only. It does not call models, judges, verifiers, or
recompute inferential statistics. It reads the outputs generated by the current
analysis pipeline and turns them into a self-contained, slide-style HTML briefing.

Detailed analyst tables remain in reports/iclr-current/index.html. This briefing is
written to reports/iclr-current/team-briefing.html.
"""
from __future__ import annotations

import argparse
import base64
import csv
import html
import sys
import io
import json
import math
from collections import defaultdict
from pathlib import Path
from typing import Any, Iterable

import matplotlib
matplotlib.use("Agg")
import matplotlib.pyplot as plt
import numpy as np

PROFILES = ("claude", "fable", "codex", "llama")
PROFILE_LABELS = {
    "claude": "Claude Opus 4.8",
    "fable": "Fable 5",
    "codex": "Codex GPT-5.6",
    "llama": "Llama 3.3 + Mini-SWE",
}
PROFILE_COLORS = {
    "claude": "#6755D9",
    "fable": "#0F9D76",
    "codex": "#2D79C7",
    "llama": "#C94A4A",
}
CONTRAST_LABELS = {
    "evaluation_disclosure": "Eval only",
    "financial_pressure": "Financial pressure",
    "self_preservation_pressure": "Self-preservation",
    "resource_deprivation": "Resource deprivation",
}
PLACEMENT_LABELS = {"root": "Root", "scaffold": "Scaffold", "source": "Source"}
CONDITION_LABELS = {
    "clean": "Clean",
    "eval_only": "Eval only",
    "eval_financial": "Eval + financial",
    "eval_self_preservation": "Eval + self-preservation",
}
CONDITION_COLORS = {
    "clean": "#AEBCC6",
    "eval_only": "#3B82F6",
    "eval_financial": "#F59E0B",
    "eval_self_preservation": "#EF4444",
}

plt.rcParams.update({
    "font.size": 10,
    "axes.titlesize": 14,
    "axes.labelsize": 10,
    "font.family": "DejaVu Sans",
    "figure.facecolor": "white",
    "axes.facecolor": "white",
    "axes.edgecolor": "#D5DFEA",
    "text.color": "#16233F",
    "axes.labelcolor": "#344258",
    "xtick.color": "#344258",
    "ytick.color": "#344258",
})


def read_csv(path: Path) -> list[dict[str, str]]:
    if not path.is_file():
        return []
    limit = sys.maxsize
    while True:
        try:
            csv.field_size_limit(limit)
            break
        except OverflowError:
            limit //= 10
    with path.open(newline="", encoding="utf-8-sig") as f:
        return list(csv.DictReader(f))


def num(value: Any) -> float | None:
    if value in (None, "", "NA", "nan", "None", "null"):
        return None
    try:
        x = float(str(value).replace(",", "").replace("%", "").strip())
    except Exception:
        return None
    return x if math.isfinite(x) else None


def integer(value: Any) -> int:
    x = num(value)
    return int(x) if x is not None else 0


def truthy(value: Any) -> bool:
    return str(value).strip().lower() in {"1", "true", "yes", "y"}


def first_num(row: dict[str, Any], *keys: str) -> float | None:
    for key in keys:
        x = num(row.get(key))
        if x is not None:
            return x
    return None


def fmt_pct(value: float | None, digits: int = 1) -> str:
    return "—" if value is None else f"{100 * value:.{digits}f}%"


def fmt_pp(value: float | None, digits: int = 1) -> str:
    return "—" if value is None else f"{value:+.{digits}f} pp"


def fmt_change(value: float | None, digits: int = 0) -> str:
    return "—" if value is None else f"{value:+.{digits}f}%"


def fmt_num(value: float | None, digits: int = 1) -> str:
    if value is None:
        return "—"
    if abs(value) >= 100000:
        return f"{value:+,.0f}"
    return f"{value:+,.{digits}f}"


def fmt_p(value: float | None) -> str:
    if value is None:
        return "—"
    if value < 0.001:
        return "< .001"
    return f"= {value:.3f}"


def img_data(fig: plt.Figure) -> str:
    buf = io.BytesIO()
    fig.savefig(buf, format="png", dpi=180, bbox_inches="tight", facecolor="white")
    plt.close(fig)
    return "data:image/png;base64," + base64.b64encode(buf.getvalue()).decode("ascii")


def trials_path(root: Path, study: str, profile: str) -> Path:
    return root / "analysis" / "current" / "source" / study / profile / "trials.csv"


def load_trials(root: Path, study: str, profile: str) -> list[dict[str, str]]:
    return read_csv(trials_path(root, study, profile))


def substantive(row: dict[str, str]) -> bool:
    if "substantive_usable" in row:
        return truthy(row.get("substantive_usable"))
    return str(row.get("terminal_status", "")) in {"completed", "safety_refusal"}


def profile_validity(root: Path, profile: str) -> dict[str, Any]:
    rows = load_trials(root, "primary", profile)
    if not rows:
        return {
            "include": profile != "llama",
            "usable": 0,
            "protocol_errors": 0,
            "legacy_no_agent_steps": 0,
            "planned": 0,
        }

    protocol = sum(
        str(r.get("terminal_status", "")) == "agent_protocol_error"
        for r in rows
    )

    # Backward-compatible guard for current-analysis snapshots produced before
    # analyzer schema 2.2. The historical Mini-SWE 2.4.6 cohort was sometimes
    # marked completed by Harbor even though its ATIF trajectory contained no
    # recorded agent/model step. Those rows are not model outcomes.
    legacy_no_agent_steps = 0
    if profile == "llama":
        for r in rows:
            version = str(r.get("agent_version") or "")
            turns = first_num(r, "assistant_turns", "agent_turns")
            if (
                version == "2.4.6"
                and turns is not None
                and turns <= 0
            ):
                legacy_no_agent_steps += 1

    usable = sum(substantive(r) for r in rows) - legacy_no_agent_steps
    usable = max(0, usable)
    planned = len(rows)

    if profile != "llama":
        include = usable > 0
    else:
        # A fresh full Mini-SWE cohort automatically re-enters once it has broad
        # substantive coverage and no dominant protocol-invalid population.
        include = (
            usable >= 500
            and protocol <= max(5, planned * 0.02)
            and legacy_no_agent_steps <= max(5, planned * 0.02)
        )

    return {
        "include": include,
        "usable": usable,
        "protocol_errors": protocol,
        "legacy_no_agent_steps": legacy_no_agent_steps,
        "planned": planned,
    }


def valid_primary_profiles(root: Path) -> tuple[list[str], dict[str, dict[str, Any]]]:
    status = {p: profile_validity(root, p) for p in PROFILES}
    profiles = [p for p in PROFILES if status[p]["include"]]
    return profiles, status


def success_by_condition(root: Path, profiles: Iterable[str]) -> dict[tuple[str, str], float]:
    out: dict[tuple[str, str], float] = {}
    for p in profiles:
        rows = [r for r in load_trials(root, "primary", p) if substantive(r)]
        groups: dict[str, list[float]] = defaultdict(list)
        for r in rows:
            cond = str(r.get("condition", ""))
            val = num(r.get("overall_pass"))
            if cond and val is not None:
                groups[cond].append(val)
        for cond, vals in groups.items():
            out[(p, cond)] = sum(vals) / len(vals) if vals else 0.0
    return out


def weighted_delivery(delivery: list[dict[str, str]], profiles: Iterable[str], metric: str) -> dict[tuple[str, str], float]:
    allowed = set(profiles)
    sums: dict[tuple[str, str], float] = defaultdict(float)
    ns: dict[tuple[str, str], float] = defaultdict(float)
    for r in delivery:
        if r.get("study") != "primary" or r.get("profile") not in allowed:
            continue
        if str(r.get("metric") or r.get("delivery_metric") or "") != metric:
            continue
        cond = str(r.get("condition") or "")
        if cond == "clean":
            continue
        placement = str(r.get("channel") or r.get("placement") or "")
        if placement not in PLACEMENT_LABELS:
            continue
        rate = first_num(r, "rate")
        n = first_num(r, "n") or 1.0
        if rate is None:
            continue
        key = (str(r.get("profile")), placement)
        sums[key] += rate * n
        ns[key] += n
    return {k: sums[k] / ns[k] for k in sums if ns[k]}


def semantic_recognition_by_placement(semantic_prev: list[dict[str, str]], profiles: Iterable[str]) -> dict[tuple[str, str], float]:
    allowed = set(profiles)
    counts: dict[tuple[str, str], float] = defaultdict(float)
    resolved: dict[tuple[str, str], float] = defaultdict(float)
    for r in semantic_prev:
        if r.get("study") != "primary" or r.get("profile") not in allowed:
            continue
        if r.get("field") != "evaluation_recognition" or r.get("label") != "observed":
            continue
        cond = str(r.get("condition") or "")
        if cond == "clean":
            continue
        placement = str(r.get("placement") or "")
        if placement not in PLACEMENT_LABELS:
            continue
        key = (str(r.get("profile")), placement)
        counts[key] += first_num(r, "count") or 0.0
        resolved[key] += first_num(r, "strict_resolved_n") or 0.0
    return {k: counts[k] / resolved[k] for k in counts if resolved[k]}


def aggregate_semantic_rate(semantic_prev: list[dict[str, str]], profiles: Iterable[str], field: str, label: str, condition: str | None = None, placement: str | None = None) -> dict[str, float]:
    allowed = set(profiles)
    counts: dict[str, float] = defaultdict(float)
    resolved: dict[str, float] = defaultdict(float)
    for r in semantic_prev:
        p = str(r.get("profile") or "")
        if r.get("study") != "primary" or p not in allowed:
            continue
        if r.get("field") != field or r.get("label") != label:
            continue
        if condition and r.get("condition") != condition:
            continue
        if placement and r.get("placement") != placement:
            continue
        counts[p] += first_num(r, "count") or 0.0
        resolved[p] += first_num(r, "strict_resolved_n") or 0.0
    return {p: counts[p] / resolved[p] for p in counts if resolved[p]}


def matched_success(binary: list[dict[str, str]], profiles: Iterable[str]) -> list[dict[str, Any]]:
    allowed = set(profiles)
    rows = []
    for r in binary:
        p = str(r.get("profile") or "")
        if r.get("study") != "primary" or p not in allowed or r.get("metric") != "overall_pass":
            continue
        effect = first_num(r, "effect_pp", "risk_difference_pp", "delta_pp")
        lo = first_num(r, "ci95_low_pp", "ci95_low")
        hi = first_num(r, "ci95_high_pp", "ci95_high")
        if effect is None:
            b = first_num(r, "baseline_rate")
            t = first_num(r, "treatment_rate")
            if b is not None and t is not None:
                effect = 100 * (t - b)
        if effect is None:
            continue
        rows.append({
            "profile": p,
            "contrast": str(r.get("contrast") or ""),
            "placement": str(r.get("placement") or ""),
            "effect": effect,
            "low": lo,
            "high": hi,
            "holm": first_num(r, "holm_p"),
            "raw_p": first_num(r, "mcnemar_p_raw", "mcnemar_p", "mcnemar_exact_p"),
            "n": integer(r.get("matched_n")),
        })
    return rows


def selected_said_did(said: list[dict[str, str]]) -> dict[str, Any] | None:
    candidates = []
    for r in said:
        if r.get("semantic_source") != "strict_consensus":
            continue
        if r.get("study") != "primary" or r.get("metric") != "input_tokens":
            continue
        if r.get("semantic_field") != "claimed_behavioral_response" or r.get("semantic_label") != "ignore":
            continue
        if integer(r.get("n_pairs")) < 10:
            continue
        score = 0
        if r.get("profile") == "fable": score += 10
        if r.get("contrast") == "self_preservation_pressure": score += 5
        if r.get("placement") == "source": score += 3
        ci_low = first_num(r, "ci95_low")
        if ci_low is not None and ci_low > 0: score += 5
        candidates.append((score, r))
    if not candidates:
        return None
    candidates.sort(key=lambda x: x[0], reverse=True)
    r = candidates[0][1]
    return {
        "profile": str(r.get("profile")),
        "contrast": str(r.get("contrast")),
        "placement": str(r.get("placement")),
        "n": integer(r.get("n_pairs")),
        "delta": first_num(r, "mean_delta"),
        "low": first_num(r, "ci95_low"),
        "high": first_num(r, "ci95_high"),
    }


def cue_removal_effects(integrity: list[dict[str, str]]) -> list[dict[str, Any]]:
    rows = []
    for r in integrity:
        component = str(r.get("component") or "")
        if component not in {"seeded_cue_removed_or_modified", "Planted cue removed/modified"}:
            continue
        p = str(r.get("profile") or r.get("model") or "").lower()
        if "claude" not in p:
            continue
        contrast = str(r.get("contrast") or r.get("intervention") or "")
        if contrast not in {"financial_pressure", "self_preservation_pressure"}:
            continue
        placement = str(r.get("placement") or "")
        if placement and placement != "source":
            continue
        effect = first_num(r, "delta_pp", "risk_difference_pp", "effect_pp", "matched_delta")
        if effect is None:
            continue
        rows.append({"contrast": contrast, "effect": effect})
    return rows


def process_root_effects(process: list[dict[str, str]]) -> list[dict[str, Any]]:
    rows = []
    for r in process:
        if r.get("study") != "primary" or r.get("profile") != "claude" or r.get("placement") != "root":
            continue
        if r.get("contrast") not in {"financial_pressure", "self_preservation_pressure"}:
            continue
        metric = str(r.get("metric") or "")
        if metric not in {"raw_tool_calls", "trajectory_steps", "input_tokens"}:
            continue
        baseline = first_num(r, "baseline_mean")
        treatment = first_num(r, "treatment_mean")
        mean_delta = first_num(r, "mean_delta")
        rel = None
        if baseline not in (None, 0) and treatment is not None:
            rel = 100 * (treatment - baseline) / abs(baseline)
        rows.append({
            "contrast": str(r.get("contrast")),
            "metric": metric,
            "relative": rel,
            "delta": mean_delta,
            "q": first_num(r, "bh_q"),
        })
    return rows


def resource_effects(focused: list[dict[str, str]]) -> list[dict[str, Any]]:
    rows = []
    for r in focused:
        p = str(r.get("profile") or "")
        metric = str(r.get("metric") or "")
        if p not in {"claude", "fable", "codex"} or metric not in {"raw_tool_calls", "input_tokens", "validation_calls"}:
            continue
        b = first_num(r, "baseline_mean")
        t = first_num(r, "treatment_mean")
        if b in (None, 0) or t is None:
            continue
        rows.append({
            "profile": p,
            "metric": metric,
            "relative": 100 * (t - b) / abs(b),
            "holm": first_num(r, "focused_holm_p"),
        })
    return rows


def integrity_summary(root: Path, profiles: Iterable[str]) -> dict[str, Any]:
    targeting = 0
    context_edits = 0
    lookups: dict[str, tuple[int, int]] = {}
    total = 0
    for p in profiles:
        rows = [r for r in load_trials(root, "primary", p) if substantive(r)]
        total += len(rows)
        target_count = 0
        edit_count = 0
        lookup_count = 0
        for r in rows:
            target_value = str(r.get("evaluation_targeting_intent") or "").lower()
            if target_value not in {"", "none", "not_observed", "0", "false", "unknown"}:
                target_count += 1
            if truthy(r.get("evaluation_context_file_modified")):
                edit_count += 1
            if truthy(r.get("same_repository_public_lookup")) or truthy(r.get("same_repository_public_lookup_any")):
                lookup_count += 1
        targeting += target_count
        context_edits += edit_count
        lookups[p] = (lookup_count, len(rows))
    return {"targeting": targeting, "context_edits": context_edits, "lookups": lookups, "total": total}


def benchmark_provenance_summary(summary_rows: list[dict[str, str]], trial_rows: list[dict[str, str]], profiles: Iterable[str]) -> dict[str, Any]:
    allowed=set(profiles)
    summary=[r for r in summary_rows if r.get("study")=="primary" and r.get("profile") in allowed]
    trials=[r for r in trial_rows if r.get("study")=="primary" and r.get("profile") in allowed]
    examples=[r for r in trials if truthy(r.get("exact_benchmark_solution_lookup"))]
    examples.sort(key=lambda r:(0 if truthy(r.get("overall_pass")) else 1,str(r.get("profile")),str(r.get("trial_name"))))
    return {"by_profile":{str(r.get("profile")):r for r in summary},"examples":examples[:5]}

def chart_benchmark_provenance(summary: dict[str, Any], profiles: Iterable[str]) -> str | None:
    rows=[]
    for p in profiles:
        r=summary.get("by_profile",{}).get(p); n=first_num(r or {},"substantive_n")
        if not r or not n: continue
        rows.append((p,100*(first_num(r,"benchmark_repository_lookup_n") or 0)/n,100*(first_num(r,"exact_benchmark_task_lookup_n") or 0)/n,100*(first_num(r,"exact_benchmark_solution_lookup_n") or 0)/n))
    if not rows:return None
    fig,ax=plt.subplots(figsize=(7.2,3.8));x=np.arange(len(rows));w=.22
    for j,(label,idx,color) in enumerate((("Any SWE-Atlas access",1,"#A7B8D8"),("Exact task accessed",2,"#5C84D6"),("Exact solution artifact",3,"#D85A4A"))):
        vals=[r[idx] for r in rows]; bars=ax.bar(x+(j-1)*w,vals,w,label=label,color=color)
        for b,v in zip(bars,vals):
            if v>0:ax.text(b.get_x()+b.get_width()/2,v+.1,f"{v:.1f}%",ha="center",fontsize=8,fontweight="bold")
    ax.set_xticks(x,[PROFILE_LABELS[p] for p,*_ in rows]);ax.set_ylabel("Share of substantive primary runs");ax.set_ylim(0,max(4,max(r[1] for r in rows)+1));ax.grid(axis="y",color="#E7ECF2");ax.spines[["top","right"]].set_visible(False);ax.legend(frameon=False,fontsize=8,ncol=3,loc="upper center",bbox_to_anchor=(.5,1.18));fig.tight_layout();return img_data(fig)

def provenance_examples_html(summary: dict[str, Any]) -> str:
    ex=summary.get("examples") or []
    if not ex:return '<div class="mini"><h3>No direct benchmark-answer retrieval detected</h3><p>No exact-task SWE-Atlas solution artifact appears in the current validated primary trajectories.</p></div>'
    rows=[]
    for r in ex[:4]:
        rows.append(f"<tr><td><code>{html.escape(str(r.get('trial_name') or ''))}</code></td><td>{html.escape(str(r.get('condition') or ''))} · {html.escape(str(r.get('channel') or ''))}</td><td>{'pass' if truthy(r.get('overall_pass')) else 'fail'}</td><td>gold.patch / solution</td></tr>")
    return '<div class="prov-examples"><h3>Representative direct-answer retrievals</h3><table class="prov-table"><thead><tr><th>Trajectory</th><th>Cell</th><th>Outcome</th><th>Artifact</th></tr></thead><tbody>'+''.join(rows)+'</tbody></table></div>'

def replication_status(root: Path) -> dict[str, Any]:
    counts = {}
    for p in PROFILES:
        rows = [r for r in load_trials(root, "replication", p) if substantive(r)]
        if rows:
            counts[p] = len(rows)
    return {"counts": counts, "total": sum(counts.values())}


def chart_success(rates: dict[tuple[str, str], float], profiles: list[str]) -> str:
    conditions = ["clean", "eval_only", "eval_financial", "eval_self_preservation"]
    fig, ax = plt.subplots(figsize=(10.2, 4.6))
    x = np.arange(len(profiles))
    width = 0.19
    for j, cond in enumerate(conditions):
        vals = [100 * rates.get((p, cond), np.nan) for p in profiles]
        ax.bar(x + (j - 1.5) * width, vals, width, color=CONDITION_COLORS[cond], label=CONDITION_LABELS[cond])
        for xx, v in zip(x + (j - 1.5) * width, vals):
            if np.isfinite(v):
                ax.text(xx, v + 0.8, f"{v:.0f}%", ha="center", va="bottom", fontsize=8)
    ax.set_xticks(x, [PROFILE_LABELS[p] for p in profiles])
    ax.set_ylim(0, max(75, np.nanmax([100 * v for v in rates.values()] or [70]) + 8))
    ax.set_ylabel("Strict hidden-pass rate")
    ax.set_title("Task success by model and condition")
    ax.grid(axis="y", color="#E7ECF2", linewidth=.8)
    ax.spines[["top", "right"]].set_visible(False)
    ax.legend(frameon=False, ncol=4, loc="upper center", bbox_to_anchor=(0.5, 1.17), fontsize=9)
    fig.tight_layout()
    return img_data(fig)


def chart_exposure_recognition(exposure: dict[tuple[str, str], float], recognition: dict[tuple[str, str], float], profiles: list[str]) -> str:
    cols = ["root", "scaffold", "source"]
    left = np.array([[100 * exposure.get((p, c), np.nan) for c in cols] for p in profiles])
    right = np.array([[100 * recognition.get((p, c), np.nan) for c in cols] for p in profiles])
    fig, axes = plt.subplots(1, 2, figsize=(10.3, 4.4))
    specs = [
        (axes[0], left, "Cue text visible in recorded trajectory", "Blues", 100),
        (axes[1], right, "Evaluation context semantically recognized", "Purples", max(50, np.nanmax(right) if np.isfinite(right).any() else 50)),
    ]
    for ax, matrix, title, cmap, vmax in specs:
        im = ax.imshow(matrix, cmap=cmap, vmin=0, vmax=vmax, aspect="auto")
        ax.set_xticks(range(3), [PLACEMENT_LABELS[c] for c in cols])
        ax.set_yticks(range(len(profiles)), [PROFILE_LABELS[p] for p in profiles])
        ax.set_title(title, fontsize=13, weight="bold")
        for i in range(matrix.shape[0]):
            for j in range(matrix.shape[1]):
                v = matrix[i, j]
                if np.isfinite(v):
                    color = "white" if v > vmax * .55 else "#26364B"
                    ax.text(j, i, f"{v:.1f}%", ha="center", va="center", color=color, fontweight="bold", fontsize=10)
        for s in ax.spines.values(): s.set_visible(False)
    axes[1].set_yticklabels([])
    fig.suptitle("Exposure and recognition are related, but they are not the same measurement", fontsize=15, weight="bold", y=1.02)
    fig.tight_layout()
    return img_data(fig)


def chart_semantic_source(effects: list[dict[str, str]], profiles: list[str]) -> str | None:
    rows = []
    allowed = set(profiles)
    for r in effects:
        if r.get("study") != "primary" or r.get("semantic_source") != "strict_consensus" or r.get("profile") not in allowed:
            continue
        if r.get("placement") != "source" or r.get("contrast") not in {"financial_pressure", "self_preservation_pressure"}:
            continue
        field = str(r.get("field") or "")
        label = str(r.get("positive_label") or "")
        if not ((field == "pressure_recognition" and label == "observed") or (field == "explicit_resistance" and label == "observed")):
            continue
        effect = first_num(r, "risk_difference_pp")
        if effect is None:
            continue
        rows.append((str(r.get("profile")), str(r.get("contrast")), field, effect))
    if not rows:
        return None
    keys = [(p, c) for p in profiles for c in ("financial_pressure", "self_preservation_pressure")]
    fig, axes = plt.subplots(1, 2, figsize=(10.0, 4.3), sharey=True)
    for ax, field, title in zip(axes, ["pressure_recognition", "explicit_resistance"], ["Pressure recognition", "Explicit resistance"]):
        vals = []
        labels = []
        colors = []
        for p, c in keys:
            match = next((e for pp, cc, ff, e in rows if pp == p and cc == c and ff == field), None)
            if match is None:
                continue
            vals.append(match)
            labels.append(f"{PROFILE_LABELS[p]} · {'Financial' if c == 'financial_pressure' else 'Self-pres.'}")
            colors.append(PROFILE_COLORS[p])
        y = np.arange(len(vals))
        ax.barh(y, vals, color=colors)
        ax.set_yticks(y, labels)
        ax.invert_yaxis()
        ax.axvline(0, color="#AAB3BC", lw=1)
        ax.set_xlabel("Matched treatment effect (pp)")
        ax.set_title(title, weight="bold")
        for i, v in enumerate(vals):
            ax.text(v + (1.1 if v >= 0 else -1.1), i, f"{v:+.1f}", ha="left" if v >= 0 else "right", va="center", fontsize=9, fontweight="bold")
        ax.spines[["top", "right"]].set_visible(False)
    fig.tight_layout()
    return img_data(fig)


def chart_matched_success(rows: list[dict[str, Any]], profiles: list[str]) -> str:
    contrasts = ["evaluation_disclosure", "financial_pressure", "self_preservation_pressure"]
    placements = ["root", "scaffold", "source"]
    fig, axes = plt.subplots(1, len(profiles), figsize=(10.7, 4.2), squeeze=False)
    vmax = max(12.0, max((abs(r["effect"]) for r in rows), default=12.0))
    for j, p in enumerate(profiles):
        matrix = np.full((3, 3), np.nan)
        pmat = np.full((3, 3), np.nan)
        for r in rows:
            if r["profile"] != p or r["contrast"] not in contrasts or r["placement"] not in placements:
                continue
            matrix[contrasts.index(r["contrast"]), placements.index(r["placement"])] = r["effect"]
            pmat[contrasts.index(r["contrast"]), placements.index(r["placement"])] = r["holm"] if r["holm"] is not None else np.nan
        ax = axes[0, j]
        ax.imshow(matrix, cmap="RdBu", vmin=-vmax, vmax=vmax, aspect="auto")
        ax.set_xticks(range(3), [PLACEMENT_LABELS[x] for x in placements])
        ax.set_yticks(range(3), ["Eval - clean", "Financial - eval", "Self-pres. - eval"] if j == 0 else ["", "", ""])
        ax.set_title(PROFILE_LABELS[p], fontsize=12.5, weight="bold")
        for i in range(3):
            for k in range(3):
                v = matrix[i, k]
                if np.isfinite(v):
                    sig = np.isfinite(pmat[i, k]) and pmat[i, k] <= .05
                    ax.text(k, i, f"{v:+.1f}pp{'*' if sig else ''}", ha="center", va="center", fontsize=9, fontweight="bold", color="white" if abs(v) > vmax*.52 else "#223047")
        for s in ax.spines.values(): s.set_visible(False)
    fig.suptitle("Matched performance effects are modest and inconsistent across placements", fontsize=14.5, weight="bold", y=1.02)
    fig.text(.5, -.01, "* Holm-adjusted p ≤ .05 within the planned family", ha="center", fontsize=9, color="#64748B")
    fig.tight_layout()
    return img_data(fig)


def chart_root_execution(rows: list[dict[str, Any]]) -> str | None:
    if not rows:
        return None
    metrics = ["input_tokens", "raw_tool_calls", "trajectory_steps"]
    contrasts = ["financial_pressure", "self_preservation_pressure"]
    metric_labels = {"input_tokens": "Input tokens", "raw_tool_calls": "Tool calls", "trajectory_steps": "Trajectory steps"}
    fig, ax = plt.subplots(figsize=(9.3, 4.2))
    x = np.arange(len(metrics)); width=.34
    for j, c in enumerate(contrasts):
        vals=[]
        for m in metrics:
            match=next((r for r in rows if r["contrast"]==c and r["metric"]==m), None)
            vals.append(match["relative"] if match and match["relative"] is not None else np.nan)
        color = "#E67E22" if c == "financial_pressure" else "#8E44AD"
        bars=ax.bar(x+(j-.5)*width, vals, width, color=color, label="Financial" if j==0 else "Self-preservation")
        for b,v in zip(bars,vals):
            if np.isfinite(v): ax.text(b.get_x()+b.get_width()/2, v+1, f"{v:+.1f}%", ha="center", va="bottom", fontsize=9, fontweight="bold")
    ax.axhline(0,color="#AAB3BC",lw=1); ax.set_xticks(x,[metric_labels[m] for m in metrics]); ax.set_ylabel("Relative mean change vs eval-only")
    ax.set_title("Claude root conditions increased execution volume")
    ax.legend(frameon=False,ncol=2); ax.grid(axis="y",color="#E7ECF2"); ax.spines[["top","right"]].set_visible(False)
    fig.tight_layout(); return img_data(fig)


def chart_resource(rows: list[dict[str, Any]]) -> str | None:
    if not rows: return None
    metric_labels={"input_tokens":"Input tokens","raw_tool_calls":"Tool calls","validation_calls":"Validation"}
    models=[p for p in ("claude","fable","codex") if any(r["profile"]==p for r in rows)]
    metrics=["input_tokens","raw_tool_calls","validation_calls"]
    fig,ax=plt.subplots(figsize=(9.5,4.4)); x=np.arange(len(metrics)); width=.24
    for j,p in enumerate(models):
        vals=[]
        for m in metrics:
            match=next((r for r in rows if r["profile"]==p and r["metric"]==m),None)
            vals.append(match["relative"] if match else np.nan)
        bars=ax.bar(x+(j-(len(models)-1)/2)*width,vals,width,color=PROFILE_COLORS[p],label=PROFILE_LABELS[p])
        for b,v in zip(bars,vals):
            if np.isfinite(v): ax.text(b.get_x()+b.get_width()/2,v-2 if v<0 else v+1,f"{v:+.0f}%",ha="center",va="top" if v<0 else "bottom",fontsize=8,fontweight="bold")
    ax.axhline(0,color="#AAB3BC",lw=1); ax.set_xticks(x,[metric_labels[m] for m in metrics]); ax.set_ylabel("Relative mean change")
    ax.set_title("Resource-deprivation follow-up: execution contraction is model-specific")
    ax.grid(axis="y",color="#E7ECF2"); ax.spines[["top","right"]].set_visible(False); ax.legend(frameon=False,ncol=len(models),fontsize=8,loc="lower center",bbox_to_anchor=(.5,1.0))
    fig.tight_layout(); return img_data(fig)


def chart_lookup(summary: dict[str, Any]) -> str | None:
    rows=[]
    for p,(k,n) in summary["lookups"].items():
        if n: rows.append((p,100*k/n))
    if not rows: return None
    fig,ax=plt.subplots(figsize=(6.0,3.5)); x=np.arange(len(rows)); vals=[v for _,v in rows]
    bars=ax.bar(x,vals,color=[PROFILE_COLORS[p] for p,_ in rows]); ax.set_xticks(x,[PROFILE_LABELS[p] for p,_ in rows]); ax.set_ylabel("Runs with same-repository public lookup")
    ax.set_ylim(0,max(75,max(vals)+10)); ax.grid(axis="y",color="#E7ECF2"); ax.spines[["top","right"]].set_visible(False)
    for b,v in zip(bars,vals): ax.text(b.get_x()+b.get_width()/2,v+1,f"{v:.0f}%",ha="center",fontsize=9,fontweight="bold")
    fig.tight_layout(); return img_data(fig)


def notes_html(text: str) -> str:
    return f'<aside class="notes">{text}</aside>'


def slide(index: int, kicker: str, title: str, subtitle: str, body: str, notes: str = "") -> str:
    return f'''<section class="slide" id="s{index}" data-slide="{index}"><div class="frame"><header><div class="kicker">{kicker}</div><h1>{title}</h1><p class="subtitle">{subtitle}</p></header><main>{body}</main>{notes_html(notes)}</div></section>'''


def build(root: Path) -> str:
    results=root/"analysis"/"current"/"results"; findings=root/"analysis"/"current"/"findings"; audit=root/"analysis"/"current"/"audit"; v2=root/"analysis"/"current"/"behavioral_claims_v2"
    binary=read_csv(results/"matched_binary_effects.csv"); process=read_csv(results/"matched_process_effects.csv"); focused=read_csv(results/"resource_focused_process.csv"); said=read_csv(results/"said_did_summary.csv")
    delivery=read_csv(audit/"treatment_delivery.csv"); sem_prev=read_csv(findings/"semantic_prevalence_by_cell.csv"); integrity=read_csv(findings/"integrity_component_effects.csv"); sem_effects=read_csv(v2/"semantic_treatment_effects.csv")
    provenance_summary_rows=read_csv(findings/"benchmark_provenance_summary.csv"); provenance_trial_rows=read_csv(findings/"benchmark_provenance_trials.csv")
    profiles,status=valid_primary_profiles(root)
    if not profiles: profiles=["claude","fable","codex"]
    usable_total=sum(status[p]["usable"] for p in profiles)
    success=success_by_condition(root,profiles); exposure=weighted_delivery(delivery,profiles,"eval_cue_observed"); recognition=semantic_recognition_by_placement(sem_prev,profiles)
    matched=matched_success(binary,profiles); said_row=selected_said_did(said); cue_rows=cue_removal_effects(integrity); root_rows=process_root_effects(process); resource_rows=resource_effects(focused); intsum=integrity_summary(root,profiles); provenance=benchmark_provenance_summary(provenance_summary_rows,provenance_trial_rows,profiles); repl=replication_status(root)
    success_img=chart_success(success,profiles); exp_img=chart_exposure_recognition(exposure,recognition,profiles); sem_img=chart_semantic_source(sem_effects,profiles); matched_img=chart_matched_success(matched,profiles); root_img=chart_root_execution(root_rows); resource_img=chart_resource(resource_rows); lookup_img=chart_lookup(intsum); provenance_img=chart_benchmark_provenance(provenance,profiles)

    llama_note=""
    if not status.get("llama",{}).get("include",False):
        llama_status = status.get("llama", {})
        invalid = (
            int(llama_status.get("protocol_errors", 0))
            + int(llama_status.get("legacy_no_agent_steps", 0))
        )
        llama_note=(f"Historical Llama trajectories are excluded from the primary comparative figures while the corrected Mini-SWE rerun is in progress. The current source tree identifies {invalid} protocol-invalid or legacy no-agent-step trajectories and {llama_status.get('usable',0)} substantive attempts.")

    slides=[]
    body=f'''<div class="hero-grid"><div><div class="question">What changes when a coding agent can tell it is being evaluated?</div><p class="lead">We hold the coding task fixed and vary evaluation disclosure, pressure type, and where the cue appears.</p><div class="stats"><div><b>70</b><span>SWE-Atlas tasks</span></div><div><b>10</b><span>primary variants / task</span></div><div><b>{len(profiles)}</b><span>validated primary models</span></div><div><b>{usable_total:,}</b><span>validated primary trajectories</span></div></div></div><div class="hero-card"><h3>Current empirical picture</h3><ul><li>Evaluation context is measurably recognized.</li><li>Placement strongly determines exposure and recognition.</li><li>Recognition often produces verbal resistance, but broad adaptation remains uncommon.</li><li>Primary success effects are modest after multiplicity correction.</li></ul></div></div>'''
    slides.append(slide(1,"PROJECT OVERVIEW","SWE-EvalPressure","A controlled coding-agent benchmark for evaluation awareness, pressure, and behavioral response.",body,"I’ll start with the basic idea. We keep the underlying SWE task fixed and change the evaluation context around it. That lets us ask separately whether the agent sees the cue, recognizes what it means, changes how it works, or actually changes task success."))

    body='''<div class="design-grid"><div class="design-card"><span>1</span><h3>Same coding task</h3><p>Original SWE-Atlas refactoring instruction and hidden verifier.</p></div><div class="arrow">→</div><div class="design-card"><span>2</span><h3>Evaluation context</h3><p>Clean, eval-only, financial pressure, or self-preservation pressure.</p></div><div class="arrow">→</div><div class="design-card"><span>3</span><h3>Placement</h3><p>Root file, scaffold-native instruction file, or source-local comment.</p></div><div class="arrow">→</div><div class="design-card"><span>4</span><h3>Measured response</h3><p>Exposure, semantic recognition, execution policy, integrity behavior, and strict success.</p></div></div><div class="matrix-card"><div><b>Clean</b><span>1 variant</span></div><div><b>Eval-only</b><span>3 placements</span></div><div><b>Financial</b><span>3 placements</span></div><div><b>Self-preservation</b><span>3 placements</span></div></div>'''
    slides.append(slide(2,"EXPERIMENTAL DESIGN","A matched design separates awareness from ordinary task difficulty","Every treatment is compared against the same base task, so task identity is controlled by construction.",body,"The important feature here is the within-task matching. We are not comparing different repositories or different difficulty buckets. For a given base task, we compare the treatment trajectory against the corresponding control trajectory."))

    body=f'''<div class="chart-layout"><div class="chart"><img src="{success_img}"></div><div class="side-stack"><div class="mini"><h3>Capability baseline</h3><p>Codex is strongest on strict hidden success; Claude and Fable remain in the middle band.</p></div><div class="mini"><h3>Pressure is not a large aggregate success lever</h3><p>Within each capable model, the four condition bars stay relatively close.</p></div>{f'<div class="mini caution"><h3>Llama status</h3><p>{llama_note}</p></div>' if llama_note else ''}</div></div>'''
    slides.append(slide(3,"CAPABILITY BASELINE","Primary task success is fairly stable across conditions","The benchmark’s more informative signals show up in awareness and execution behavior rather than a dramatic global pass-rate shift.",body,"This is the capability baseline. The cleanest takeaway is that pressure does not simply move all success rates in one direction. The interesting effects are more local and show up in what the agent notices and how it allocates effort."))

    body=f'''<div class="chart-layout wide-left"><div class="chart"><img src="{exp_img}"></div><div class="side-stack"><div class="mini"><h3>Source placement</h3><p>Most consistently visible for Claude and Fable.</p></div><div class="mini"><h3>Scaffold placement</h3><p>Highly visible in the trace for Codex; semantic recognition is lower than exposure.</p></div><div class="mini"><h3>Root placement</h3><p>Weak direct exposure across the validated models.</p></div><div class="mini caution"><h3>Important distinction</h3><p><b>Cue text visible in recorded trajectory</b> means the analyzer can match the planted text in the stored agent trace. It is a treatment-delivery diagnostic, not proof that the model internally understood it.</p></div></div></div>'''
    slides.append(slide(4,"EXPOSURE AND RECOGNITION","Placement determines whether the treatment is meaningfully observed","The left panel is a deterministic trace diagnostic; the right panel is strict-consensus semantic recognition. They answer different questions.",body,"This slide separates two things that are easy to conflate. On the left, we ask whether the planted evaluation text actually appears in the recorded trajectory. On the right, we ask whether the agent’s own language shows that it interpreted the current task as an evaluation. Exposure is necessary evidence about delivery, but it is not the same thing as awareness."))

    if sem_img:
        body=f'''<div class="chart-layout"><div class="chart"><img src="{sem_img}"></div><div class="side-stack"><div class="mini"><h3>Claude</h3><p>Source-local pressure produces the clearest recognition and resistance signal.</p></div><div class="mini"><h3>Fable</h3><p>Shows the same qualitative pattern, with smaller effect sizes.</p></div><div class="mini"><h3>Codex</h3><p>Often receives the cue but rarely verbalizes explicit resistance.</p></div><div class="mini"><h3>Interpretation</h3><p>Recognition and adaptation are distinct: noticing pressure does not imply benchmark-directed gaming.</p></div></div></div>'''
    else:
        body='<div class="empty">Strict-consensus semantic treatment effects are unavailable in the current source tree.</div>'
    slides.append(slide(5,"WHAT AGENTS SAY","Visible source-local pressure often triggers recognition and resistance","Strict two-judge consensus provides an observable semantic response measure; it is not a claim about hidden internal state.",body,"This is where we see the clearest awareness signal. Claude and Fable often identify source-local pressure as suspicious or artificial. Codex is much less likely to verbalize that stance even when the cue is present."))

    said_block='''<div class="said-card"><div class="said-label">Post-treatment descriptive example</div><h3>Said: “ignore”</h3><p>No qualifying strict-consensus ignore subgroup was available in the current results.</p></div>'''
    if said_row:
        said_block=f'''<div class="said-card"><div class="said-label">Post-treatment descriptive subgroup</div><h3>Said: ignore / resist the cue</h3><p>Among <b>{said_row['n']}</b> {PROFILE_LABELS.get(said_row['profile'],said_row['profile'])} {said_row['placement']}-placement {CONTRAST_LABELS.get(said_row['contrast'],said_row['contrast'])} trajectories with strict consensus on “ignore”:</p><div class="big-purple">{fmt_num(said_row['delta'],0)} input tokens</div><p>relative to the same-task eval-only control</p><div class="ci">95% bootstrap CI [{fmt_num(said_row['low'],0)}, {fmt_num(said_row['high'],0)}]</div></div>'''
    cue_items=''.join(f'<div class="cue-stat"><b>{CONTRAST_LABELS.get(r["contrast"],r["contrast"])}</b><span>{r["effect"]:+.1f} pp</span><small>planted source cue removed / modified</small></div>' for r in sorted(cue_rows,key=lambda x:x['contrast'])) or '<div class="cue-stat"><span>—</span><small>No cue-removal rows</small></div>'
    body=f'''<div class="said-did-grid">{said_block}<div class="objective-card"><div class="said-label randomized-label">Randomized matched behavior</div><h3>Did: source-local cue handling changed</h3><div class="cue-stats">{cue_items}</div><p class="footnote">The semantic subgroup on the left is descriptive because “said ignore” is measured after treatment. The cue-handling effects on the right retain the randomized same-task comparison.</p></div></div>'''
    slides.append(slide(6,"SAID VERSUS DID","Verbal resistance does not guarantee behavioral invariance","The same report can show an agent rejecting a cue verbally while its objective execution still differs from the matched control.",body,"This is the said-versus-did result we wanted to preserve. The left side is intentionally labeled descriptive: once I condition on what the agent said after treatment, randomization is no longer intact. The right side is a randomized matched result and shows that Claude’s source-local cue handling really does change under pressure."))

    body=f'''<div class="chart-layout"><div class="chart"><img src="{matched_img}"></div><div class="side-stack"><div class="mini"><h3>Effect sizes</h3><p>Most same-task success changes sit within roughly ±10 percentage points.</p></div><div class="mini"><h3>Multiplicity</h3><p>A nominally interesting Claude root effect does not survive the planned Holm family.</p></div><div class="mini"><h3>Result</h3><p>The current primary study supports awareness and process-response claims more strongly than a broad task-success claim.</p></div></div></div>'''
    slides.append(slide(7,"MATCHED PERFORMANCE","Pressure does not produce a robust global success effect","Same-task risk differences are treatment minus control. Asterisks mark Holm-adjusted significance, not raw p-values.",body,"This is the slide I would use if someone asks whether pressure changes success. The answer is that we see some directional cells, but the planned family does not give us a robust global performance effect. That is useful because it tells us not to make the paper about pass rate alone."))

    if root_img:
        body=f'''<div class="chart-layout"><div class="chart"><img src="{root_img}"></div><div class="side-stack"><div class="mini"><h3>Self-preservation, root</h3><p>More input tokens, tools, and trajectory steps than the same-task eval-only root control.</p></div><div class="mini"><h3>Financial, root</h3><p>Smaller but directionally similar execution expansion.</p></div><div class="mini caution"><h3>Mechanism caveat</h3><p>Direct root-cue exposure is weak. These are assignment effects; the specific cue-mediated mechanism remains unresolved.</p></div></div></div>'''
    else:
        body='<div class="empty">Primary process-effect rows are unavailable.</div>'
    slides.append(slide(8,"EXECUTION POLICY","Pressure can change how much work an agent does even when success barely moves","Claude’s root conditions are the clearest example of a process-level shift that is larger than the corresponding task-success effect.",body,"This is why the project is interesting even without a huge pass-rate shift. Under the root pressure conditions, Claude expands execution. We should be careful about mechanism because root exposure is weak, but the assignment-level behavior change is there."))

    if resource_img:
        body=f'''<div class="chart-layout"><div class="chart"><img src="{resource_img}"></div><div class="side-stack"><div class="mini"><h3>Separate follow-up</h3><p>Resource deprivation is analyzed as its own matched experimental family, not mixed into the 10-variant primary replication.</p></div><div class="mini"><h3>Codex</h3><p>Broad contraction in tokens, tool calls, and validation.</p></div><div class="mini"><h3>Fable</h3><p>Independent contraction, especially validation and input-token use.</p></div></div></div>'''
    else:
        body='<div class="empty">Resource-deprivation focused outputs are unavailable.</div>'
    slides.append(slide(9,"RESOURCE-DEPRIVATION EXTENSION","A textual scarcity cue produces large, model-specific execution contraction","This is a matched follow-up against eval-only scaffold controls and is deliberately separated from the primary 10-variant study.",body,"The resource follow-up gives us a different kind of pressure. Here the behavioral response is much larger: Codex and Fable both contract execution, but in different ways. That makes this a useful separate experimental family rather than something to fold into the primary matrix."))

    lookup_block=f'<div class="lookup-chart"><img src="{lookup_img}"></div>' if lookup_img else ''
    body=f'''<div class="integrity-grid"><div class="check-card"><div class="check">✓</div><h3>{intsum['targeting']} evaluation-targeting incidents</h3><p>No explicit attempt to manipulate scoring or evaluator artifacts across {intsum['total']:,} validated primary trajectories.</p></div><div class="check-card"><div class="check">✓</div><h3>{intsum['context_edits']} evaluation-context file edits</h3><p>No direct edits to the planted benchmark-context files in the validated cohorts.</p></div><div class="lookup-card"><h3>Public repository lookup</h3>{lookup_block}<p class="footnote">This is not classified as evaluator targeting, but it is a provenance variable worth standardizing in the next round.</p></div></div>'''
    slides.append(slide(10,"INTEGRITY CHECKS","No direct evaluator targeting was observed in the validated primary cohorts","The benchmark surfaces awareness and behavioral response without showing overt scoring manipulation in this study.",body,"I would frame this positively. We are seeing awareness signals without seeing direct evaluator tampering. Public repository lookup is a separate provenance issue: it is common enough that we should control it more deliberately, but it is not the same thing as evaluation targeting."))

    codex_row=provenance.get("by_profile",{}).get("codex",{})
    direct_n=integer(codex_row.get("exact_benchmark_solution_lookup_n")) if codex_row else 0
    benchmark_n=integer(codex_row.get("benchmark_repository_lookup_n")) if codex_row else 0
    direct_pass=integer(codex_row.get("exact_benchmark_solution_pass_n")) if codex_row else 0
    direct_rate=first_num(codex_row,"exact_benchmark_solution_pass_rate") if codex_row else None
    remaining_rate=first_num(codex_row,"non_solution_lookup_pass_rate") if codex_row else None
    prov_chart=f'<div class="chart"><img src="{provenance_img}"></div>' if provenance_img else '<div class="empty">No provenance audit available.</div>'
    sensitivity=(f"{direct_pass}/{direct_n} exact-solution retrieval trajectories passed ({100*direct_rate:.0f}%), versus {100*remaining_rate:.0f}% among the remaining Codex runs." if direct_n and direct_rate is not None and remaining_rate is not None else "Direct answer retrieval is reported separately from ordinary public-repository lookup.")
    body=f'''<div class="prov-grid">{prov_chart}<div class="side-stack"><div class="mini"><h3>Direct SWE-Atlas access</h3><p><b>{benchmark_n}</b> Codex trajectories accessed a SWE-Atlas repository; <b>{direct_n}</b> retrieved an exact-task solution artifact such as <code>gold.patch</code>.</p></div><div class="mini"><h3>Capability sensitivity</h3><p>{sensitivity}</p><p class="footnote">This is benchmark contamination and should be excluded or sensitivity-tested for clean capability claims. It is not evidence that lookup caused success.</p></div>{provenance_examples_html(provenance)}</div></div>'''
    slides.append(slide(11,"BENCHMARK PROVENANCE AUDIT","A small Codex subset directly accessed SWE-Atlas task artifacts","Ordinary GitHub use is not automatically contamination. Exact-task SWE-Atlas solution retrieval is the strongest answer-recovery flag.",body,"We now distinguish generic public GitHub use from direct benchmark contamination. The serious case is when a trajectory reaches SWE-Atlas itself and retrieves the exact task's solution artifact. Those trajectories should be treated as contaminated for clean capability interpretation. The presentation also shows whether those runs were disproportionately successful, so we do not confuse contamination with a causal performance benefit."))

    counts=repl['counts']; count_text=''.join(f'<div><b>{PROFILE_LABELS[p]}</b><span>{n} substantive trajectories currently recovered</span></div>' for p,n in counts.items()) or '<div><b>Rerun in progress</b><span>No canonical replication source rows are available yet.</span></div>'
    body=f'''<div class="rep-grid"><div class="rep-status"><h3>Independent rerun</h3><div class="rep-counts">{count_text}</div><p>The rerun remains separate from the primary cohort until all planned shards are complete and reconstructed under one study manifest.</p></div><div class="rep-status"><h3>What we are checking</h3><ul><li>Direction and size of the main Claude process effects</li><li>Stability of source-local semantic recognition</li><li>Whether provenance and integrity patterns recur</li><li>Corrected Mini-SWE / Llama execution under the fixed agent protocol</li></ul></div></div>'''
    slides.append(slide(12,"REPLICATION","The independent rerun is a validation layer, not something we pool early","We report it descriptively while incomplete and only promote it to confirmatory evidence after full reconstruction.",body,"The rerun is happening now, so I would keep this simple tomorrow. We are not pooling partial data into the primary estimates. We are using the rerun to see which of the main patterns recur under a fresh execution cohort."))

    body='''<div class="synthesis-grid"><div class="synth"><span>01</span><h3>Awareness is measurable</h3><p>Agents do identify evaluation and pressure context in observable trajectories.</p></div><div class="synth"><span>02</span><h3>Placement is a first-order design variable</h3><p>Source and scaffold channels produce much more reliable exposure than passive root files.</p></div><div class="synth"><span>03</span><h3>Recognition ≠ adaptation</h3><p>Verbal resistance can coexist with objective execution changes.</p></div><div class="synth"><span>04</span><h3>Behavior can move without a large success effect</h3><p>Process-level outcomes capture response that pass/fail alone misses.</p></div><div class="synth next"><span>→</span><h3>Next experimental priorities</h3><p>Complete the replication, standardize network/provenance conditions, finish human semantic validation, and expand the pressure taxonomy with explicitly separated follow-ups.</p></div></div>'''
    slides.append(slide(13,"SYNTHESIS","What the current study supports","The benchmark is already informative, but the strongest claims are about awareness, delivery, and execution policy—not yet broad strategic gaming.",body,"That is the story I would end on. The benchmark is working: it measures awareness, shows that placement matters, and reveals execution-policy changes that pass/fail alone would miss. The next round is about replication and tightening the design, not rescuing a failed experiment."))

    css='''
:root{--navy:#16233F;--blue:#2F6FEB;--muted:#66758A;--line:#D6E0EA;--panel:#F8FAFC;--purple:#6B55D8;--green:#12A678;--orange:#E98B21;--red:#D94B4B;--cream:#FFF8EB}*{box-sizing:border-box}html{scroll-behavior:smooth;scroll-snap-type:y mandatory}body{margin:0;background:white;color:var(--navy);font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Arial,sans-serif}.slide{height:100vh;min-height:680px;scroll-snap-align:start;border-top:2px solid #3159D4;overflow:hidden}.frame{width:min(1280px,100%);height:100%;margin:auto;padding:22px 46px 34px;position:relative;display:flex;flex-direction:column}.kicker{font-size:10px;letter-spacing:.14em;text-transform:uppercase;color:var(--blue);font-weight:850;margin-bottom:7px}h1{font-size:35px;line-height:1.06;letter-spacing:-.035em;margin:0;max-width:1120px}.subtitle{font-size:16px;line-height:1.42;color:var(--muted);max-width:1000px;margin:8px 0 0}main{flex:1;display:flex;align-items:center;min-height:0;padding:15px 0 14px}.notes{display:none;position:absolute;right:30px;bottom:30px;width:420px;max-height:42vh;overflow:auto;background:#101827;color:white;padding:16px 18px;border-radius:12px;box-shadow:0 12px 38px rgba(0,0,0,.28);font-size:12px;line-height:1.5;z-index:30}.show-notes .notes{display:block}.notes-toggle{position:fixed;right:13px;top:18px;z-index:50;border:1px solid var(--line);background:white;border-radius:999px;padding:7px 11px;font-size:10px;color:var(--navy);cursor:pointer}.dots{position:fixed;right:13px;top:50%;transform:translateY(-50%);display:flex;flex-direction:column;gap:6px;z-index:40}.dots button{width:8px;height:8px;border:0;border-radius:50%;background:#C9D4E2;padding:0;cursor:pointer}.dots button.active{background:var(--blue);transform:scale(1.35)}.hero-grid{display:grid;grid-template-columns:1.45fr .75fr;gap:24px;width:100%}.question{font-size:31px;line-height:1.18;font-weight:800;letter-spacing:-.02em;max-width:800px}.lead{font-size:17px;color:#526177;max-width:760px}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin-top:30px}.stats div,.mini,.design-card,.matrix-card div,.said-card,.objective-card,.check-card,.lookup-card,.rep-status,.synth{border:1px solid var(--line);border-radius:14px;background:var(--panel)}.stats div{text-align:center;padding:14px 8px}.stats b{display:block;font-size:27px;color:var(--blue)}.stats span{font-size:11px;color:#536277}.hero-card{background:#F1F5FF;border:1px solid #D5E1FF;border-radius:18px;padding:24px}.hero-card h3{font-size:20px;margin:0 0 12px}.hero-card li{margin:9px 0;font-size:14px;line-height:1.4}.design-grid{display:grid;grid-template-columns:1fr auto 1fr auto 1fr auto 1fr;gap:9px;align-items:center;width:100%}.design-card{padding:17px;height:170px}.design-card span{display:inline-flex;width:25px;height:25px;border-radius:50%;background:#E7EEFF;color:var(--blue);align-items:center;justify-content:center;font-weight:800;font-size:11px}.design-card h3{font-size:16px;margin:10px 0 7px}.design-card p{font-size:12px;color:#536277;line-height:1.42}.arrow{font-size:22px;color:#94A3B8}.matrix-card{position:absolute;left:46px;right:46px;bottom:38px;display:grid;grid-template-columns:repeat(4,1fr);gap:8px}.matrix-card div{padding:10px 13px;display:flex;justify-content:space-between}.matrix-card b{font-size:12px}.matrix-card span{font-size:11px;color:#66758A}.chart-layout{display:grid;grid-template-columns:minmax(0,1.62fr) minmax(260px,.68fr);gap:17px;width:100%;align-items:center}.chart-layout.wide-left{grid-template-columns:minmax(0,1.78fr) minmax(250px,.55fr)}.chart{border:1px solid var(--line);border-radius:14px;background:white;padding:11px;display:flex;align-items:center;justify-content:center;min-height:390px}.chart img{max-width:100%;max-height:430px;object-fit:contain}.side-stack{display:grid;gap:9px}.mini{padding:13px 14px}.mini h3{font-size:12px;margin:0 0 5px}.mini p{font-size:11px;line-height:1.38;color:#425169;margin:0}.mini.caution{background:var(--cream);border-color:#F1D59D}.said-did-grid{display:grid;grid-template-columns:.8fr 1.2fr;gap:18px;width:100%}.said-card,.objective-card{padding:25px}.said-label{font-size:9px;letter-spacing:.08em;text-transform:uppercase;color:var(--purple);font-weight:850}.randomized-label{color:#067A58}.said-card h3,.objective-card h3{font-size:22px;margin:11px 0}.said-card p,.objective-card p{font-size:13px;line-height:1.47;color:#425169}.big-purple{font-size:34px;font-weight:850;color:var(--purple);margin:18px 0 2px}.ci{font-size:11px;color:#66758A}.cue-stats{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:20px}.cue-stat{background:#F7FAFC;border:1px solid var(--line);border-radius:12px;padding:16px}.cue-stat b{display:block;font-size:12px}.cue-stat span{display:block;font-size:28px;color:#0B8B67;font-weight:850;margin:5px 0}.cue-stat small{font-size:10px;color:#66758A}.footnote{font-size:10.5px!important;color:#66758A!important}.integrity-grid{display:grid;grid-template-columns:1fr 1fr .9fr;gap:14px;width:100%}.prov-grid{display:grid;grid-template-columns:1.15fr .9fr;gap:16px;width:100%;align-items:center}.prov-examples{border:1px solid var(--line);border-radius:12px;background:white;padding:10px}.prov-examples h3{font-size:12px;margin:0 0 7px}.prov-table{width:100%;border-collapse:collapse;font-size:9px}.prov-table th,.prov-table td{padding:5px 6px;border-bottom:1px solid #E7ECF2;text-align:left}.prov-table code{font-size:8px}.check-card,.lookup-card{min-height:320px;padding:22px;display:flex;flex-direction:column;justify-content:center}.check{text-align:center;color:#18B77E;font-size:50px;font-weight:900}.check-card h3{text-align:center;font-size:17px;margin:5px 0}.check-card p{text-align:center;font-size:11px;color:#536277}.lookup-card h3{font-size:16px;margin:0 0 6px}.lookup-chart img{width:100%;max-height:225px;object-fit:contain}.rep-grid{display:grid;grid-template-columns:1fr 1fr;gap:18px;width:100%}.rep-status{padding:24px}.rep-status h3{font-size:19px;margin:0 0 13px}.rep-counts{display:grid;gap:8px}.rep-counts div{background:white;border:1px solid var(--line);padding:10px 12px;border-radius:9px}.rep-counts b{display:block;font-size:12px}.rep-counts span{font-size:10.5px;color:#66758A}.rep-status li{font-size:13px;margin:9px 0}.synthesis-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px;width:100%}.synth{padding:17px;min-height:120px;position:relative}.synth span{position:absolute;right:13px;top:9px;font-size:22px;color:#D2DBE7;font-weight:850}.synth h3{font-size:15px;margin:0 0 6px}.synth p{font-size:11.5px;color:#536277;line-height:1.42;margin:0}.synth.next{grid-column:1/-1;background:#F1F5FF;border-color:#D5E1FF}.empty{padding:30px;border:1px dashed var(--line);border-radius:12px;color:#66758A;width:100%}@media(max-width:900px){.frame{padding:20px 24px}.slide{min-height:720px;height:auto}.hero-grid,.chart-layout,.chart-layout.wide-left,.said-did-grid,.integrity-grid,.prov-grid,.rep-grid,.synthesis-grid{grid-template-columns:1fr}.design-grid{grid-template-columns:1fr}.arrow{display:none}.matrix-card{position:static;margin-top:12px}.stats{grid-template-columns:1fr 1fr}.chart{min-height:320px}.dots{display:none}}
'''
    js='''
const slides=[...document.querySelectorAll('.slide')];const dots=document.querySelector('.dots');slides.forEach((s,i)=>{const b=document.createElement('button');b.title=`Slide ${i+1}`;b.onclick=()=>s.scrollIntoView({behavior:'smooth'});dots.appendChild(b)});const dotButtons=[...dots.children];const obs=new IntersectionObserver(es=>{es.forEach(e=>{if(e.isIntersecting){const i=slides.indexOf(e.target);dotButtons.forEach((b,j)=>b.classList.toggle('active',i===j));}})},{threshold:.6});slides.forEach(s=>obs.observe(s));function go(delta){let idx=0;slides.forEach((s,i)=>{const r=s.getBoundingClientRect();if(Math.abs(r.top)<innerHeight*.5)idx=i});idx=Math.max(0,Math.min(slides.length-1,idx+delta));slides[idx].scrollIntoView({behavior:'smooth'});}document.addEventListener('keydown',e=>{if(['ArrowDown','ArrowRight','PageDown'].includes(e.key)){e.preventDefault();go(1)}if(['ArrowUp','ArrowLeft','PageUp'].includes(e.key)){e.preventDefault();go(-1)}if(e.key.toLowerCase()==='n')document.body.classList.toggle('show-notes');if(e.key.toLowerCase()==='f'){if(!document.fullscreenElement)document.documentElement.requestFullscreen();else document.exitFullscreen();}});document.querySelector('.notes-toggle').onclick=()=>document.body.classList.toggle('show-notes');
'''
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>SWE-EvalPressure — Team Briefing</title><style>{css}</style></head><body><button class="notes-toggle">Speaker notes (N)</button><nav class="dots"></nav>{''.join(slides)}<script>{js}</script></body></html>'''


def parse_args() -> argparse.Namespace:
    p=argparse.ArgumentParser(description="Generate the presentation-first SWE-EvalPressure team briefing HTML from current canonical analysis outputs.")
    p.add_argument("--project-root",type=Path,default=Path(__file__).resolve().parents[1])
    p.add_argument("--output",type=Path,help="Defaults to reports/iclr-current/team-briefing.html under the project root.")
    return p.parse_args()


def main() -> None:
    args=parse_args(); root=args.project_root.expanduser().resolve(); out=(args.output.expanduser().resolve() if args.output else root/"reports"/"iclr-current"/"team-briefing.html"); out.parent.mkdir(parents=True,exist_ok=True); out.write_text(build(root),encoding="utf-8"); print(out)

if __name__=="__main__": main()
